struct Node {long value; struct Node * next;};
long entry(int n);
struct Node * make(long value);
long entry(int n) {
struct Node * head = make(((long)(n)));
if ((!(head))) {
return ((long)((-(1))));
}
struct Node * tail = make(((long)((n + 1))));
if ((!(tail))) {
free(head);
return ((long)((-(2))));
}
(head)->next = tail;
struct Node * next = (head)->next;
long result = ((head)->value + (next)->value);
free(tail);
free(head);
return result;
}

struct Node * make(long value) {
struct Node * p = calloc(((unsigned long)(1)), sizeof(struct Node));
if ((!(p))) {
return 0;
}
(p)->value = value;
(p)->next = 0;
return p;
}
